import os, re
root = "/bench/repo"
pat = re.compile(r'(?:\.store|\.Store|stores|ts\.Store|ts|a\.store|d\.store)\.GetUser\(|s\.GetUser\(')
# also d.GetUser on mysql driver - skip if in store/db
func_re = re.compile(r'^func\s+(\([^)]+\)\s+)?(\w+)')

results = []
for dirpath, _, files in os.walk(root):
    if '/proto/' in dirpath or '/web/' in dirpath:
        continue
    for f in files:
        if not f.endswith('.go'):
            continue
        path = os.path.join(dirpath, f)
        rel = path[len(root)+1:]
        with open(path) as fh:
            lines = fh.readlines()
        current = None
        for i, line in enumerate(lines, 1):
            m = func_re.match(line)
            if m:
                recv = m.group(1) or ""
                name = m.group(2)
                current = name
            if re.search(r'\.GetUser\(', line) or re.search(r'(^|[^\w])GetUser\(', line):
                # filter lookalikes
                if re.search(r'GetUser(Identity|Setting|ByPAT|Refresh|Personal|Webhook|RSS|Stats|Service)', line):
                    continue
                if 'func ' in line and 'GetUser(' in line:
                    continue  # definitions
                if 'APIV1Service.GetUser' in line or 'Service.GetUser' in line:
                    continue
                if '.GetUser()' in line:  # proto getter
                    continue
                if 'req.Msg' in line or 'req *connect' in line:
                    continue
                results.append((current or '?', rel, i, line.strip()[:120]))

for r in results:
    print(f"{r[0]}:{r[2]} — {r[1]}  |  {r[3]}")
